/**
 * @method
 * @name searchExchrt
 * @description 환율조회한다.
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} currTpCd desc
 * @param {string} procTpCd 1:exa db,2:mail
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.searchExchrt = function (vScrenID, dtsObj, currTpCd, procTpCd) {
    let retVal = scwin.bnsCheckExaDb(vScrenID, dtsObj, procTpCd);
    if (retVal == 0) {
        let param = '&{P}V_CURR_TP_CD=' + currTpCd;
        let dsNm = 'BNS_SVR_RUN_INFO';
        let qryId = 'lds.stf.bnscommon.select.readExchrt';
        dtsObj.SyncLoad = "true";
        scwin.searchBns(vScrenID, dtsObj, dsNm, qryId, param);
        if (dtsObj.getTotalRow() > 0) {
            return dtsObj.getCellData(1, 'EXCHRT');
        }
    }
    return 1;
};

/**
 * @method
 * @name showInstAlert
 * @description 정상이 아니면 확인메시지를 보여준다.
 * @param {string} dtsObj 기관데이터
 * @param {string} rowpos row 위치
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.showInstAlert = function (dtsObj, rowpos) {
    if (dtsObj.getCellData(rowpos, 'INST_STAT_CD') != '1') {
        $c.win.alert('기관상태가 정상인 기관만 선택 가능 합니다.</br>선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.');
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name bnsCheckExaDb
 * @description Exa DB 사용가능한지 체크한다.
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} procTpCd 1:exa db,2:mail
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.bnsCheckExaDb = function (vScrenID, dtsObj, procTpCd) {
    let msg = '';
    msg += '서비스 이용에 불편을 드려 죄송합니다.';
    msg += '</br>잠시후 다시 이용해 주세요.';
    msg += '</br>이와 관련해서 문의사항이 있으시면 시스템 담당자에게 연락해 주세요.';

    //exa 조회
    let param = '';
    let dsNm = 'BNS_SVR_RUN_INFO';
    let qryId = 'lds.stf.bnscommon.select.readMailAndExaServiceStat';
    dtsObj.SyncLoad = "true";
    scwin.searchBns(vScrenID, dtsObj, dsNm, qryId, param);
    let exa = dtsObj.getCellData(1, 'EXA_SVC_RUN_YN');
    let mail = dtsObj.getCellData(1, 'MAIL_SVC_RUN_YN');
    if (procTpCd == '1' && exa != 'Y') {
        $c.win.alert(msg);
        return 1;
    } else if (procTpCd == '2' && mail != 'Y') {
        $c.win.alert(msg);
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name searchBns
 * @description 데이터를 조회한다.
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} url desc
 * @param {string} param desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.searchBns = async function (vScrenID, dtsObj, url, param) {
    const sbmOptionsListCd = {
        id: "sbm_"+dtsObj,
        action: url,
        method: "get",
        target: dtsObj+"=body",
    };

    await $c.sbm.executeDynamic(sbmOptionsListCd, param);

    // if (dsNm == 'BNS_INST_INFO') {
    //     dtsObj.InsertRow(dtsObj.getFocusedRowIndex());
    //     //resetCdValue(dtsObj);		

    // }
};

/**
 * @method
 * @name searchBns1
 * @description 데이터를 조회한다.
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} dsNm desc
 * @param {string} qryId desc
 * @param {string} param desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.searchBns1 = function (vScrenID, dtsObj, dsNm, qryId, param) {
    let url = "/listingCommon.do?method=listGeneral";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + dsNm;
    url += "&queryId=" + qryId;
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += param;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    if (dsNm == 'BNS_INST_INFO') {
        dtsObj.InsertRow(dtsObj.getFocusedRowIndex());
        //resetCdValue(dtsObj);		

    }
};

/**
 * @method
 * @name resetCdValue
 * @description 콤보데이터를 'CODE VALUE' 형태로 재가공한다.
 * @param {string} cbDs desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.resetCdValue = function (cbDs) {
    for (let i = 1; i <= cbDs.getTotalRow(); i++) {
        cbDs.setCellData(i, "TEXT", cbDs.getCellData(i, "VALUE") + ' ' + cbDs.getCellData(i, "TEXT"));
    }
};

