/**
 * @method
 * @name setBnsComboToCode
 * @description 2개 이상의 콤보데이터들을 설정한다.
 *              부연 : 코드값이 30개 이하인 것들 권장
 *              호출시 : let arrCid = [];
 *                       arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
 *                       arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} arrCid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setBnsComboToCode = async function (vScrenID, arrCid) {
    const codeOptions = [];
    for (let i = 0; i < arrCid.length; i++) {
        arrCid[i].cid = scwin.getMappingColNm(arrCid[i].cid);

        let filter = [];
        //통화코드
        if (arrCid[i].cid == 'CURR_TP_CD') { 
            filter =  ["cdVal==1,2,3,4,5"];
        }
        //시장조치구분코드
        else if (arrCid[i].cid == 'BND_MKTACT_TP_CD') {
            filter =  ["cdVal!=104,105,999"];
        }
        //상장수수료면제사유코드
        else if (arrCid[i].cid == 'BND_LIST_FEE_EXMPT_RSN_CD') {
            filter =  ["cdVal!=6"];
        }

        let tmp =  {
            code: arrCid[i].cid,
            action: "/api/bonds/common/api/commCode/commCodeValue-select?type=R&codeList=" + arrCid[i].cid,
            firstRow: ["", ""],
            filter : filter,
            compID: arrCid[i].cnm
        }
        codeOptions.push(tmp);
    }
    await $c.data.setCommonCode(codeOptions);
};

/**
 * @method
 * @name setBnsComboToCode1
 * @description 2개 이상의 콤보데이터들을 설정한다.
 *              부연 : 코드값이 30개 이하인 것들 권장
 *              호출시 : let arrCid = [];
 *                       arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
 *                       arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} arrCid desc
 * @param {string} defValue desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setBnsComboToCode1 = function (vScrenID, dtsObj, arrCid, defValue) {
    let arrCD_ID = "";
    for (let i = 0; i < arrCid.length; i++) {
        arrCid[i].cid = scwin.getMappingColNm(arrCid[i].cid);
        arrCD_ID += "'" + arrCid[i].cid + "',";
    }
    arrCD_ID = arrCD_ID.substring(0, arrCD_ID.length - 1);
    let url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M=" + arrCD_ID;
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    dtsObj.SyncLoad = "false";
    let stdCbd = "",
        i, j;
    let objCod;
    let cd = '';
    let cdNm = '';
    for (let i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dtsObj.getTotalRow(); j++) {
            cd = dtsObj.getCellData(j, "VALUE");
            cdNm = dtsObj.getCellData(j, "TEXT");
            if (dtsObj.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                //시장조치구분코드
                if (dtsObj.getCellData(j, "CD_ENG_NM") == 'BND_MKTACT_TP_CD') {
                    if (cd == '104' || cd == '105' || cd == '999') {
                        continue;
                    }
                }
                strCbd += "," + cd + "^" + cd + ' ' + cdNm;
            }
        }
        objCod.CBData = "0^" + defValue + strCbd;
    }
};

/**
 * @method
 * @name setBnsComboToCode2
 * @description 2개 이상의 콤보데이터들을 설정한다.
 *              부연 : 코드값이 30개 이하인 것들 권장
 *              호출시 : let arrCid = [];
 *                       arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
 *                       arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} arrCid desc
 * @param {string} defValue desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setBnsComboToCode2 = function (vScrenID, dtsObj, arrCid, defValue) {
    let arrCD_ID = "";
    for (let i = 0; i < arrCid.length; i++) {
        arrCid[i].cid = scwin.getMappingColNm(arrCid[i].cid);
        arrCD_ID += "'" + arrCid[i].cid + "',";
    }
    arrCD_ID = arrCD_ID.substring(0, arrCD_ID.length - 1);
    let url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M=" + arrCD_ID;
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    dtsObj.SyncLoad = "false";
    let stdCbd = "",
        i, j;
    let objCod;
    let cd = '';
    let cdNm = '';
    for (let i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dtsObj.getTotalRow(); j++) {
            cd = dtsObj.getCellData(j, "VALUE");
            cdNm = dtsObj.getCellData(j, "TEXT");
            if (dtsObj.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                //시장조치구분코드
                if (dtsObj.getCellData(j, "CD_ENG_NM") == 'BND_MKTACT_TP_CD') {
                    if (cd == '104' || cd == '105' || cd == '999' || cd == '313' || cd == '321') {
                        //210528 신용평가등급변경/신용평가등급수신 시장조치 제거
                        continue;
                    }
                }
                strCbd += "," + cd + "^" + cd + ' ' + cdNm;
            }
        }
        objCod.CBData = "^" + defValue + strCbd;
    }
};

/**
 * @method
 * @name setBnsCombo
 * @description 콤보데이터를 설정한다.
 * @param {string} vScrenID desc
 * @param {string} cboId desc
 * @param {string} CD_ID_M desc
 * @param {string} displayCode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setBnsCombo = async function (vScrenID, CBO_ID, CD_ID_M, displayCode) {
    if (displayCode == undefined) {
        displayCode = true;
    }
    if (displayCode) {
        const codeOptions = [
            {
                code: scwin.getMappingColNm(CD_ID_M),
                action: "/api/bonds/common/api/commCode/commCodeValue-select?type=R&codeList=" + scwin.getMappingColNm(CD_ID_M),
                firstRow: ["", ""],
                filedArr : ["text", "value"], 
                labelColumn : "text",
                valueColumn : "value",
                compID: CBO_ID
            }
        ];
        await $c.data.setCommonCode(codeOptions);
    }
};

/**
 * @method
 * @name setBnsCombo1
 * @description 인수의 DEL_CD idx를 제거 후, 콤보데이터를 설정한다.
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} CD_ID_M desc
 * @param {string} DEL_CD desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setBnsCombo1 = function (vScrenID, dtsObj, CD_ID_M, DEL_CD) {
    let url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M='" + scwin.getMappingColNm(CD_ID_M) + "'";
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    dtsObj.DeleteRow(DEL_CD);
    dtsObj.InsertRow(dtsObj.getFocusedRowIndex());
    scwin.resetCdValue(dtsObj);
};

