/**
 * @method
 * @name chgAmtToHan
 * @description 금액 한글 변환 한다.
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chgAmtToHan = function (str) {
    if (str == '' || str == undefined) return '';
    let won = new Array();
    let han1 = new Array("", "일", "이", "삼", "사", "오", "육", "칠", "팔", "구");
    let han2 = new Array("", "십", "백", "천");
    let han3 = new Array("", "만", "억", "조", "경");
    let han = '';
    let len = str.length;
    for (let i = len - 1; i >= 0; i--) {
        won[i] = han1[str.substring(len - i - 1, len - i)];
        if (i > 0 && won[i] != '') won[i] += han2[i % 4];
        if (i % 4 == 0) won[i] += han3[i / 4];
    }
    for (let i = len - 1; i >= 0; i--) {
        if (won[i].length == 2) won[i - i % 4] += '-';
        if (won[i].length == 1 && i > 0) won[i] = '';
        if (i % 4 != 0) won[i].replace('일', '');
    }
    won = won.reverse().join('').replace(/-+/g, '');
    return '(' + won + ')';
};

/**
 * @method
 * @name checkNewListIsuInfo
 * @description 신규상장 종목정보를 체크한다.
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkNewListIsuInfo =  async function (dtsObj) {
    let msg = "";
    //입력체크
    if (dtsObj.get("isuNm") == '') {
        await $c.win.alert("한글기준명을 선택하십시오.");
        return 1;
    }
    let unqIsuNm = dtsObj.get("unqIsuNm");
    let unqIsuEngNm = dtsObj.get("unqIsuEngNm");
    //고유명 앞 공백 체크 추가
    if (unqIsuNm.substring(0, 1) == ' ') {
        await $c.win.alert('한글고유명 맨앞자리에 공란이 있으니 확인하시기 바랍니다.');
        return 1;
    } else if (unqIsuEngNm.substring(0, 1) == ' ') {
        await $c.win.alert('영문고유명 맨앞자리에 공란이 있으니 확인하시기 바랍니다.');
        return 1;
    }
    let overLen = eval($c.stf.getStringSize(unqIsuNm) - 20);
    if ($c.str.trim(unqIsuNm) == '') {
        await $c.win.alert("한글 종목고유명을 입력하십시오.");
        return 1;
    } else if (overLen > 0) {
        await $c.win.alert("[ 한글고유명  ] 항목의 최대입력은 [ 20 ] byte 입니다.    </br></br>[ " + overLen + " ] byte 를 초과하였습니다.</br></br>확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return 1;
    }
    overLen = eval($c.stf.getStringSize(unqIsuEngNm) - 20);
    if ($c.str.trim(unqIsuEngNm) == '') {
        await $c.win.alert("영문 종목고유명을 입력하십시오.");
        return 1;
    } else if (overLen > 0) {
        await $c.win.alert("[ 영문고유명  ] 항목의 최대입력은 [ 20 ] byte 입니다.    </br></br>[ " + overLen + " ] byte 를 초과하였습니다.</br></br>확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return 1;
    }
    if (dtsObj.get("bndClssCd") == '') {
        await $c.win.alert("채권분류코드를 선택하십시오.");
        return 1;
    }
    if (dtsObj.get("listDd") == '') {
        await $c.win.alert("상장일을 입력하십시오.");
        return 1;
    }
    if (!$c.date.isDate($p.getComponentById("edt_ListDd").getValue(), false, "상장일")) {
        return 1;
    }
    if (dtsObj.get("redmptDd") == '') {
        await $c.win.alert("상환일을 입력하십시오.");
        return 1;
    }
    if (!$c.date.isDate($p.getComponentById("edt_RedmptDd").getValue(), false, "상환일")) {
        return 1;
    }
    if (dtsObj.get("listDd") >= dtsObj.get("redmptDd")) {
        await $c.win.alert("상환일보다 상장일이 빠릅니다. 일자를 확인바랍니다.");
        return 1;
    }
    if (dtsObj.get("bndTpCd") == '') {
        await $c.win.alert("채권유형을 선택하십시오.");
        return 1;
    }
    if (dtsObj.get("nusualBndTpCd") == '') {
        await $c.win.alert("특이채권유형을 선택하십시오.");
        return 1;
    }
    if (dtsObj.get("taxYn") == '') {
        await $c.win.alert("과세여부를 선택하십시오.");
        return 1;
    }
    if (dtsObj.get("bndIntPayDdBasTpCd") == '') {
        await $c.win.alert("이자일지급기준구분을 선택하십시오.");
        return 1;
    }
    if (dtsObj.get("intMmendTpCd") == '') {
        await $c.win.alert("이자월말구분을 선택하십시오.");
        return 1;
    }

    //특수채체크
    if (dtsObj.get("bndTpCd") == 'AB') {
        if (dtsObj.get('speclbndIsurCd') == '') {
            await $c.win.alert('특수채 발행기관 코드가 없습니다.');
            return 1;
        }
    } else {
        dtsObj.set('speclbndIsurCd', ''); // ?? 데이타맵?리스트? 뭐를 사용하는지 확인해보기 원본 dts_IsuInfo.setCellData(1, 'speclbndIsurCd', '');
    }

    //신청내용 체크 후 접수내역에서 아래사항을 체크한다.
    if (dtsObj.get("bndListProcsTpCd") == '1' ||
        dtsObj.get("bndListProcsTpCd") == '3') {
        return 0;
    }
    if (dtsObj.get("infllnkYn") == '') {
        await $c.win.alert("물가연동채구분을 확인해 주십시오.");
        cmb_InfllnkYn.Focus();
        return 1;
    } else if (dtsObj.get("infllnkYn") == 'Y' &&
        dtsObj.get("isuDdRefIdx") == '') {
        await $c.win.alert("참조지수를 확인해 주십시오.");
        edt_IsuDdRefIdx.Focus();
        return 1;
    }
    if (dtsObj.get("isurCd") != "GB035") {
        if (dtsObj.get("infllnkYn") == "Y") {
            await $c.win.alert("물가연동채구분은 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
            return 1;
        }
        if (dtsObj.get("isuDdRefIdx") != '') {
            await $c.win.alert("참조지수는 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
            return 1;
        }
    }
    //국고채이면 메시지추가
    else {
        if (dtsObj.get("isuNm").indexOf("물가") != -1 &&
            dtsObj.get("infllnkYn") != 'Y') {
            await $c.win.alert("물가연동채구분을 확인해 주십시오.");
            return 1;
        }
    }
    if (dtsObj.get("bndTpCd") == "MB" && dtsObj.get("munibndTpCd") == '') {
        await $c.win.alert("지방채구분을 선택하십시오.");
        return 1;
    }

    // 발행통화가 원화가 아닐 경우 경고창 발생
    // 단 외국채권(151)인 경우 모든 통화에대해 팝업 발생.  2023.08.23 no3
    if (dtsObj.get("currTpCd") == "") {
        await $c.win.alert("발행통화를 선택하십시오.");
        return 1;
    }
    if (scwin.vMktactCd == '151' || (scwin.vMktactCd != '151' && dtsObj.get("currTpCd") != '1')) {
        let currTpCd = $p.getComponentById("cmb_CurrTpCd").getText();
        currTpCd = currTpCd.replace(/[0-9\s]/g, '');
        msg = '발행통화가 "' + currTpCd + '" 로 설정되어 있습니다. 진행하시겠습니까?';
        if (!await $c.win.confirm(msg)) return 1;
    }
    let iss_amt = dtsObj.get("isuAmt");
    let lst_amt = dtsObj.get("listAmt");
    if (iss_amt == '') iss_amt = "0";
    if (lst_amt == '') lst_amt = "0";
    if (dtsObj.get("currTpCd") == '' || dtsObj.get("currTpCd") == '1') {
        //메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
        if (parseInt(iss_amt) < parseInt(lst_amt)) {
            await $c.win.alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
            return 1;
        }
        if (iss_amt <= 100000000) {
            await $c.win.alert("발행금액이 1억원 이하입니다.");
        } else if (iss_amt >= 1000000000000) {
            await $c.win.alert("발행금액이 1조원 이상입니다.");
        }
    }
    //메시지 추가:발행금액 10조원이상 만기가 50년 이상
    //	if(iss_amt >= 10000000000000) {
    //		await $c.win.alert('발행금액이 10조원 이상입니다.');
    //	}
    let isudd = dtsObj.get("isuDd").substr(0, 4);
    let redmptdd = dtsObj.get("redmptDd").substr(0, 4);
    if ((parseInt(redmptdd) - parseInt(isudd)) >= 50) {
        await $c.win.alert('만기가 50년 이상입니다.');
    }
    if (dtsObj.get("currTpCd") == '' ||
        dtsObj.get("currTpCd") == '1') {
        if (lst_amt <= 100000000) {
            await $c.win.alert("상장금액이 1억원 이하입니다.");
        } else if (lst_amt >= 1000000000000) {
            await $c.win.alert("상장금액이 1조원 이상입니다.");
        }
    }
    if (dtsObj.get("nusualBndTpCd") == '') {
        await $c.win.alert("특이채권유형을 선택하십시오.");
        return 1;
    } else if (dtsObj.get("nusualBndTpCd") == '2') {
        if (dtsObj.get("grtYd") == '' &&
            dtsObj.get("addYd") == '') {
            msg = '특이채권유형이 주식관련사채일때 보장수익률 또는 추가수익률을 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
    }
    // 분리형BW여부가 체크가 된경우 메세지 확인함. jackal_181210
    else if (dtsObj.get("detachBwYn") == '1') {
        if (dtsObj.get("grtYd") == '' &&
            dtsObj.get("addYd") == '') {
            msg = '분리형BW 일때 보장수익률 또는 추가수익률을 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
    }

    //보장수익률존재 시 보장수익률적용일 체크
    if (dtsObj.get("grtYd") != '' &&
        (dtsObj.get("nusualBndTpCd") != '3' &&
            dtsObj.get("nusualBndTpCd") != '4')) {
        // 분리형BW여부가 체크가 된 경우 메세지 없음. jackal_181210
        if (dtsObj.get("detachBwYn") == '1') {

        } else if (dtsObj.get("nusualBndTpCd") != '2') {
            msg = '보장수익률 입력 시 특이채권유형을 주식관련사채로 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
        if (dtsObj.get("grtYdStrtDd") == '') {
            await $c.win.alert('보장수익률 적용일을 입력하셔야 합니다.');
            return 1;
        }
    }

    //추가수익률존재 시 추가수익률적용일 체크
    if (dtsObj.get("addYd") != '') {
        // 분리형BW여부가 체크가 된 경우 메세지 없음. jackal_181210
        if (dtsObj.get("detachBwYn") == '1') {

        } else if (dtsObj.get("nusualBndTpCd") != '2') {
            msg = '추가수익률 입력 시 특이채권유형을 주식관련사채로 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
        if (dtsObj.get("addYdStrtDd") == '') {
            await $c.win.alert('추가수익률 적용일을 입력하셔야 합니다.');
            return 1;
        }
    }

    //보증방법체크 추가
    if (dtsObj.get("bndGuarTpCd") == '1' ||
        dtsObj.get("bndGuarTpCd") == '5') {
        if (dtsObj.get("grtInstCd") == '') {
            await $c.win.alert('보증사채일 경우 관련기관탭의 보증기관은 필수로 입력하셔야 합니다.');
            return 1;
        }
    }
    if (dtsObj.get("intPayMethdCd") == '') {
        await $c.win.alert("이자지급방법을 선택하십시오.");
        return 1;
    }

    /* 확인 */
    if (dtsObj.get("isuMethdIndirect") != '1' &&
        dtsObj.get("isuMethdDirect") != '1' &&
        dtsObj.get("isuMethdPpbond") != '1') {
        //2006.11.23 add
        await $c.win.alert("발행방법을 선택하십시오.");
        return 1;
    }

    //류인욱팀장님요구로 사모채도 상장(2006.1130)
    //특수채일경우만 사모가 상장될수가 있고 회사채인경우는 공모로 상장됨
    //사모채 체크 시 알림메시지 추가
    if (dtsObj.get("isuMethdPpbond") == '1' &&
        dtsObj.get("bndTpCd") != "AB") {
        //2006.11.23 add
        if (!await $c.win.confirm('발행방법이 사모채로 입력되어있습니다.</br>그래도 계속하시겠습니까?')) return 1;

        //    	if(dtsObj.NameValue(1, "BND_TP_CD") != "AB") {
        //    		await $c.win.alert('발행방법이 사모채로 입력되어있습니다.</br>사모채는 채권유형이 특수채일때만 입력가능한 항목입니다.');
        //    		return 1;
        //    	}
    }

    //메시지추가 이자지급주기는 이자계산주기보다 크거나 같아야 합니다.
    let unit = dtsObj.get("intPayUnitMms");
    let calc = dtsObj.get("intPayCalcMms");
    if (unit == '') unit = 0;
    if (calc == '') calc = 0;
    if (parseInt(unit) < parseInt(calc)) {
        if (!await $c.win.confirm('이자지급주기는 이자계산주기보다 크거나 같아야 합니다.</br>그래도 계속하시겠습니까?')) return 1;
    }
    if (dtsObj.get("hbrdbndYn") == '') {
        await $c.win.alert("신종자본증권여부를 선택하십시오.");
        return 1;
    } else if (dtsObj.get("hbrdbndYn") == 'Y') {
        if (dtsObj.get("condCapSecuTpCd") != '') {
            await $c.win.alert('신종자본증권일 경우 조건부자본증권 유형을 선택하실 수 없습니다.');
            return 1;
        }
        //추가:신종자본증권여부에 "Y"일 때 선/후/중순위에 "4.후후순위"가 아닐 경우, 채무변제 후후순위인지 확인하십시오. 그래도 진행하시겠습니까?
        else if (dtsObj.get("debtRepayRankTpCd") != '4') {
            if (!await $c.win.confirm('채무변제 후후순위인지 확인하십시오.</br>그래도 계속하시겠습니까?')) return 1;
        }
    }

    //추가:4.후후순위인데 신종자본증권여부가 "N"일 경우, 신종자본증권여부를 확인하십시오. 그래도 진행하시겠습니까?  
    if (dtsObj.get("debtRepayRankTpCd") == '4' &&
        dtsObj.get("hbrdbndYn") == 'N') {
        if (!await $c.win.confirm('신종자본증권여부를 확인하십시오.</br>그래도 계속하시겠습니까?')) return 1;
    }

    //주식관련사채 체크 추가
    if (dtsObj.get("nusualBndTpCd") == '2' &&
        dtsObj.get("stkRelCorpbndRghtTpCd") == '') {
        if (!await $c.win.confirm('주식관련탭 권리구분을  선택하셔야 합니다.</br>그래도 계속하시겠습니까?')) return 1;
    }

    //조건부자본증권 추가
    if (dtsObj.get("condCapSecuTpCd") != '') {
        //전환형이면
        if (dtsObj.get("condCapSecuTpCd") == '1') {
            //특이채권유형이 주식관련사채여야 한다.
            if (dtsObj.get("nusualBndTpCd") != '2') {
                await $c.win.alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.</br>특이채권유형을 확인바랍니다.');
                return 1;
            }
            // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.

            //주식관련사채이면 '11 조건부자본증권 전환형'이여야 한다.

            //else if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") != '11') {

            //	await $c.win.alert('주식관련탭 권리구분을 조건부자본증권 전환형으로 선택하셔야 합니다.'); 

            //	return 1;

            //}

        }
        //상각형이면 특이채권유형이 일반사채이여야 한다.
        else if (dtsObj.get("condCapSecuTpCd") == '2' &&
            dtsObj.get("nusualBndTpCd") != '1') {
            await $c.win.alert('특이채권유형을 일반사채로 선택하셔야 합니다.</br>특이채권유형을 확인바랍니다.');
            return 1;
        }
    }
    // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.
    //if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") == '11') {
    //	if(dtsObj.NameValue(1, "nusualBndTpCd") != '2') {
    //    	await $c.win.alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.</br>특이채권유형을 확인바랍니다.'); 
    //		return 1;    		
    //	}else if(dtsObj.NameValue(1, "COND_CAP_SECU_TP_CD") != '1') {
    //    	await $c.win.alert('조건부자본증권유형을 전환형으로 선택하셔야 합니다.</br>조건부자본증권유형을 확인바랍니다.'); 
    //		return 1;    		    		
    //	}
    //}

    //낙찰금리 필터링 추가 ,GB035(국고채권), 한국은행(AB101), 예금보험공사(AB526)
    if (dtsObj.get("bndMktactTpCd") != '316') {
        let isurcd = dtsObj.get("isurCd");
        if (dtsObj.get("scbdInt") == '' &&
            (isurcd == 'GB035' || isurcd == 'AB101' || isurcd == 'AB526')) {
            if (!await $c.win.confirm('낙찰금리란에 값이  없습니다.</br>그래도 계속하시겠습니까?')) return 1;
        }
    }
    if (dtsObj.get("redmptMethdTpCd") != '2' &&
        dtsObj.get("splitRedmptTpCd") != '') {
        await $c.win.alert("분할상환탭은 분할상환시에만 입력합니다. 상환방법을 확인바랍니다.");
        return 1;
    }
    if (dtsObj.get("grtYd") != '') { 
        if (dtsObj.get("grtYd") >= 20) {
            msg = "" + "보장수익률이 20%이상입니다. " + "</br>계속 진행하시겠습니까?";
            if (!await $c.win.confirm(msg)) return 1;
        } 
        if (dtsObj.get("expRedmptRto") == '100') {
            msg = "" + "보장수익률이 존재하고, 만기상환율이 100%입니다. " + "</br>계속 진행하시겠습니까?";
            if (!await $c.win.confirm(msg)) return 1;
        }
    } 
    if (dtsObj.get("asstSecutizTpCd") != '' &&
        ($p.getComponentById("cmb_CreditValuInstCd1") == '' || $p.getComponentById("cmb_SfValuYn1") != 'Y') &&
        ($p.getComponentById("cmb_CreditValuInstCd2") == '' || $p.getComponentById("cmb_SfValuYn2") != 'Y') &&
        ($p.getComponentById("cmb_CreditValuInstCd3") == '' || $p.getComponentById("cmb_SfValuYn3") != 'Y') &&
        ($p.getComponentById("cmb_CreditValuInstCd4") == '' || $p.getComponentById("cmb_SfValuYn4") != 'Y')) {
        msg = "" + "유동화채권임에도 SF를 선택하지 않았습니다. " + "</br>계속 진행하시겠습니까?";
        if (!await $c.win.confirm(msg)) return 1;
    }
    let frnBasIntTpCd1 = dtsObj.get("frnBasIntTpCd1");
    let frnBasIntTpCd2 = dtsObj.get("frnBasIntTpCd2");
    let frnBasIntTpCd3 = dtsObj.get("frnBasIntTpCd3");
    let frnBasIntMisc = dtsObj.get("frnBasIntMisc");
    if (frnBasIntTpCd1 != undefined && frnBasIntTpCd1 == '7' && $c.str.trim(frnBasIntMisc) == "") {
        await $c.win.alert("[변동금리 탭]</br>" + "기준금리상세-기타 정보를 입력하세요.");
        return 1;
    }
    if (frnBasIntTpCd2 != undefined && frnBasIntTpCd1 == '4' && $c.str.trim(frnBasIntTpCd2) == "") {
        await $c.win.alert("[변동금리 탭]</br>" + "기준금리상세-발행기관 정보를 입력하세요.");
        return 1;
    }
    if (frnBasIntTpCd3 != undefined &&
        (frnBasIntTpCd3 == '2Z' || frnBasIntTpCd3 == '3Z' || frnBasIntTpCd3 == '4Z' || frnBasIntTpCd3 == '5Z') &&
        $c.str.trim(frnBasIntMisc) == "") {
        await $c.win.alert("[변동금리 탭]</br>" + "기준금리상세-기타 정보를 입력하세요.");
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name checkNewListIsuInfoWIT
 * @description 신규상장 종목정보를 체크한다.
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkNewListIsuInfoWIT = async function (dtsObj) {
    let msg = "";
    //입력체크		
    if (dtsObj.getCellData(1, "isuNm") == '') {
        $c.win.alert("한글기준명을 선택하십시오.");
        return 1;
    }
    let unqIsuNm = dtsObj.getCellData(1, "unqIsuNm");
    let unqIsuEngNm = dtsObj.getCellData(1, "unqIsuEngNm");
    //고유명 앞 공백 체크 추가
    if (unqIsuNm.substring(0, 1) == ' ') {
        $c.win.alert('한글고유명 맨앞자리에 공란이 있으니 확인하시기 바랍니다.');
        return 1;
    } else if (unqIsuEngNm.substring(0, 1) == ' ') {
        $c.win.alert('영문고유명 맨앞자리에 공란이 있으니 확인하시기 바랍니다.');
        return 1;
    }
    let overLen = eval($c.stf.getStringSize(unqIsuNm) - 20);
    if ($c.str.trim(unqIsuNm) == '') {
        $c.win.alert("한글 종목고유명을 입력하십시오.");
        return 1;
    } else if (overLen > 0) {
        $c.win.alert("[ 한글고유명  ] 항목의 최대입력은 [ 20 ] byte 입니다.    </br></br>[ " + overLen + " ] byte 를 초과하였습니다.</br></br>확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return 1;
    }

    /*한글고유명 연번호 체크*/
    let temp = unqIsuNm.split('-');
    let temp2 = '';
    let temp3 = '';
    if (temp.length == 2) {
        temp2 = temp[1];
    }
    if (temp.length == 3) {
        temp2 = temp[1];
        temp3 = temp[2];
    }
    if (temp.length < 3) {
        $c.win.alert("한글고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuNm.focus();
        //return 1;

    } else if (temp[0].length != 5) {
        $c.win.alert("한글고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuNm.focus();
        //return 1;

    } else if (temp[1].length != 7) {
        $c.win.alert("한글고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuNm.focus();
        //return 1;

    } else if (temp[2].length != 2 && temp[2].length != 3) {
        $c.win.alert("한글고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuNm.focus();
        //return 1;

    } else if (temp2.indexOf('(') == -1) {
        $c.win.alert("한글고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuNm.focus();
        //return 1;

    } else if (temp3.indexOf(')') == -1) {
        $c.win.alert("한글고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuNm.focus();
        //return 1;

    }
    overLen = eval($c.stf.getStringSize(unqIsuEngNm) - 20);
    if ($c.str.trim(unqIsuEngNm) == '') {
        $c.win.alert("영문 종목고유명을 입력하십시오.");
        return 1;
    } else if (overLen > 0) {
        $c.win.alert("[ 영문고유명  ] 항목의 최대입력은 [ 20 ] byte 입니다.    </br></br>[ " + overLen + " ] byte 를 초과하였습니다.</br></br>확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return 1;
    }

    /*영문고유명 연번호 체크*/
    let etemp = unqIsuEngNm.split('-');
    let etemp2 = '';
    let etemp3 = '';
    if (etemp.length == 2) {
        etemp2 = etemp[1];
    }
    if (etemp.length == 3) {
        etemp2 = etemp[1];
        etemp3 = etemp[2];
    }
    if (etemp.length < 3) {
        $c.win.alert("영문고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuEngNm.focus();
        //return 1;

    } else if (etemp[0].length != 5) {
        $c.win.alert("영문고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuEngNm.focus();
        //return 1;

    } else if (etemp[1].length != 7) {
        $c.win.alert("영문고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuEngNm.focus();
        //return 1;

    } else if (etemp[2].length != 2 && etemp[2].length != 3) {
        $c.win.alert("영문고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuEngNm.focus();
        //return 1;

    } else if (etemp2.indexOf('(') == -1) {
        $c.win.alert("영문고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuEngNm.focus();
        //return 1;

    } else if (etemp3.indexOf(')') == -1) {
        $c.win.alert("영문고유명 연번호를 확인하시기 바랍니다.</br></br>고유명은 '00000-YYMM(YY-0)'의 형식이어야 합니다.");
        txb_UnqIsuEngNm.focus();
        //return 1;

    }
    if (dtsObj.getCellData(1, "bndClssCd") == '') {
        $c.win.alert("채권분류코드를 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "STRT_DD") == '') {
        $c.win.alert("WIT개시일을 입력하십시오.");
        return 1;
    }
    if (!$c.date.isDate(edt_StrtDd.getValue(), false, "WIT개시일")) {
        return 1;
    }

    //if(dtsObj.NameValue(1, "listDd") == '') {
    //    $c.win.alert("상장일을 입력하십시오."); return 1;
    //}
    if (dtsObj.getCellData(1, "listDd") != '') {
        $c.win.alert("상장일을 공란으로 입력하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "redmptDd") == '') {
        $c.win.alert("상환일을 입력하십시오.");
        return 1;
    }
    if (!$c.date.isDate(edt_RedmptDd.getValue(), false, "상환일")) {
        return 1;
    }
    if (dtsObj.getCellData(1, "listDd") >= dtsObj.getCellData(1, "redmptDd")) {
        $c.win.alert("상환일보다 상장일이 빠릅니다. 일자를 확인바랍니다.");
        return 1;
    }
    if (dtsObj.getCellData(1, "bndTpCd") == '') {
        $c.win.alert("채권유형을 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "nusualBndTpCd") == '') {
        $c.win.alert("특이채권유형을 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "taxYn") == '') {
        $c.win.alert("과세여부를 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "bndIntPayDdBasTpCd") == '') {
        $c.win.alert("이자일지급기준구분을 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "intMmendTpCd") == '') {
        $c.win.alert("이자월말구분을 선택하십시오.");
        return 1;
    }

    //특수채체크
    if (dtsObj.getCellData(1, "bndTpCd") == 'AB') {
        if (dtsObj.getCellData(1, 'speclbndIsurCd') == '') {
            $c.win.alert('특수채 발행기관 코드가 없습니다.');
            return 1;
        }
    } else {
        dtsObj.set('speclbndIsurCd', ''); // 원본 dts_IsuInfo.setCellData(1, 'speclbndIsurCd', '');
    }

    //신청내용 체크 후 접수내역에서 아래사항을 체크한다.
    if (dtsObj.getCellData(1, "bndListProcsTpCd") == '1' ||
        dtsObj.getCellData(1, "bndListProcsTpCd") == '3') {
        return 0;
    }
    if (dtsObj.getCellData(1, "infllnkYn") == '') {
        $c.win.alert("물가연동채구분을 확인해 주십시오.");
        cmb_InfllnkYn.Focus();
        return 1;
    } else if (dtsObj.getCellData(1, "infllnkYn") == 'Y' &&
        dtsObj.getCellData(1, "isuDdRefIdx") == '') {
        $c.win.alert("참조지수를 확인해 주십시오.");
        edt_IsuDdRefIdx.Focus();
        return 1;
    }
    if (dtsObj.getCellData(1, "isurCd") != "GB035") {
        if (dtsObj.getCellData(1, "infllnkYn") == "Y") {
            $c.win.alert("물가연동채구분은 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
            return 1;
        }
        if (dtsObj.getCellData(1, "isuDdRefIdx") != '') {
            $c.win.alert("참조지수는 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
            return 1;
        }
    }
    //국고채이면 메시지추가
    else {
        if (dtsObj.getCellData(1, "isuNm").indexOf("물가") != -1 &&
            dtsObj.getCellData(1, "infllnkYn") != 'Y') {
            $c.win.alert("물가연동채구분을 확인해 주십시오.");
            return 1;
        }
    }
    if (dtsObj.getCellData(1, "bndTpCd") == "MB" && dtsObj.getCellData(1, "munibndTpCd") == '') {
        $c.win.alert("지방채구분을 선택하십시오.");
        return 1;
    }

    // 발행통화가 원화가 아닐 경우 경고창 발생
    // 단 외국채권(151)인 경우 모든 통화에대해 팝업 발생.  2023.08.23 no3
    if (dtsObj.getCellData(1, "currTpCd") == "") {
        $c.win.alert("발행통화를 선택하십시오.");
        return 1;
    }
    if (scwin.vMktactCd == '151' || (scwin.vMktactCd != '151' && dtsObj.getCellData(1, "currTpCd") != '1')) {
        let currTpCd = $p.getComponentById("cmb_CurrTpCd").getText();
        currTpCd = currTpCd.replace(/[0-9\s]/g, '');
        msg = '발행통화가 "' + currTpCd + '" 로 설정되어 있습니다. 진행하시겠습니까?';
        if (!await $c.win.confirm(msg)) return 1;
    }
    let iss_amt = dtsObj.getCellData(1, "isuAmt");
    let lst_amt = dtsObj.getCellData(1, "listAmt");
    if (iss_amt == '') iss_amt = "0";
    if (lst_amt == '') lst_amt = "0";
    if (dtsObj.getCellData(1, "currTpCd") == '' ||
        dtsObj.getCellData(1, "currTpCd") == '1') {
        //메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
        if (parseInt(iss_amt) < parseInt(lst_amt)) {
            $c.win.alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
            return 1;
        }
        if (iss_amt <= 100000000) {
            $c.win.alert("발행금액이 1억원 이하입니다.");
        } else if (iss_amt >= 1000000000000) {
            $c.win.alert("발행금액이 1조원 이상입니다.");
        }
    }
    //메시지 추가:발행금액 10조원이상 만기가 50년 이상
    //	if(iss_amt >= 10000000000000) {
    //		$c.win.alert('발행금액이 10조원 이상입니다.');
    //	}
    let isudd = dtsObj.getCellData(1, "isuDd").substr(0, 4);
    let redmptdd = dtsObj.getCellData(1, "redmptDd").substr(0, 4);
    if ((parseInt(redmptdd) - parseInt(isudd)) >= 50) {
        $c.win.alert('만기가 50년 이상입니다.');
    }
    if (dtsObj.getCellData(1, "currTpCd") == '' ||
        dtsObj.getCellData(1, "currTpCd") == '1') {
        if (lst_amt <= 100000000) {
            $c.win.alert("상장금액이 1억원 이하입니다.");
        } else if (lst_amt >= 1000000000000) {
            $c.win.alert("상장금액이 1조원 이상입니다.");
        }
    }
    if (dtsObj.getCellData(1, "nusualBndTpCd") == '') {
        $c.win.alert("특이채권유형을 선택하십시오.");
        return 1;
    } else if (dtsObj.getCellData(1, "nusualBndTpCd") == '2') {
        if (dtsObj.getCellData(1, "grtYd") == '' &&
            dtsObj.getCellData(1, "addYd") == '') {
            msg = '특이채권유형이 주식관련사채일때 보장수익률 또는 추가수익률을 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
    }
    // 분리형BW여부가 체크가 된경우 메세지 확인함. jackal_181210
    else if (dtsObj.getCellData(1, "detachBwYn") == '1') {
        if (dtsObj.getCellData(1, "grtYd") == '' &&
            dtsObj.getCellData(1, "addYd") == '') {
            msg = '분리형BW 일때 보장수익률 또는 추가수익률을 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
    }

    //보장수익률존재 시 보장수익률적용일 체크
    if (dtsObj.getCellData(1, "grtYd") != '' &&
        (dtsObj.getCellData(1, "nusualBndTpCd") != '3' &&
            dtsObj.getCellData(1, "nusualBndTpCd") != '4')) {
        // 분리형BW여부가 체크가 된 경우 메세지 없음. jackal_181210
        if (dtsObj.getCellData(1, "detachBwYn") == '1') {

        } else if (dtsObj.getCellData(1, "nusualBndTpCd") != '2') {
            msg = '보장수익률 입력 시 특이채권유형을 주식관련사채로 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
        if (dtsObj.getCellData(1, "grtYdStrtDd") == '') {
            $c.win.alert('보장수익률 적용일을 입력하셔야 합니다.');
            return 1;
        }
    }

    //추가수익률존재 시 추가수익률적용일 체크
    if (dtsObj.getCellData(1, "addYd") != '') {
        // 분리형BW여부가 체크가 된 경우 메세지 없음. jackal_181210
        if (dtsObj.getCellData(1, "detachBwYn") == '1') {

        } else if (dtsObj.getCellData(1, "nusualBndTpCd") != '2') {
            msg = '추가수익률 입력 시 특이채권유형을 주식관련사채로 입력하셔야 합니다.';
            msg += '</br>그래도 계속하시겠습니까?';
            if (!await $c.win.confirm(msg)) return 1;
        }
        if (dtsObj.getCellData(1, "addYdStrtDd") == '') {
            $c.win.alert('추가수익률 적용일을 입력하셔야 합니다.');
            return 1;
        }
    }

    //보증방법체크 추가
    if (dtsObj.getCellData(1, "bndGuarTpCd") == '1' ||
        dtsObj.getCellData(1, "bndGuarTpCd") == '5') {
        if (dtsObj.getCellData(1, "grtInstCd") == '') {
            $c.win.alert('보증사채일 경우 관련기관탭의 보증기관은 필수로 입력하셔야 합니다.');
            return 1;
        }
    }
    if (dtsObj.getCellData(1, "intPayMethdCd") == '') {
        $c.win.alert("이자지급방법을 선택하십시오.");
        return 1;
    }

    /* 확인 */
    if (dtsObj.getCellData(1, "isuMethdIndirect") != '1' &&
        dtsObj.getCellData(1, "isuMethdDirect") != '1' &&
        dtsObj.getCellData(1, "isuMethdPpbond") != '1') {
        //2006.11.23 add
        $c.win.alert("발행방법을 선택하십시오.");
        return 1;
    }

    //류인욱팀장님요구로 사모채도 상장(2006.1130)
    //특수채일경우만 사모가 상장될수가 있고 회사채인경우는 공모로 상장됨
    //사모채 체크 시 알림메시지 추가
    if (dtsObj.getCellData(1, "isuMethdPpbond") == '1' &&
        dtsObj.getCellData(1, "bndTpCd") != "AB") {
        //2006.11.23 add
        if (!await $c.win.confirm('발행방법이 사모채로 입력되어있습니다.</br>그래도 계속하시겠습니까?')) return 1;

        //    	if(dtsObj.NameValue(1, "BND_TP_CD") != "AB") {
        //    		$c.win.alert('발행방법이 사모채로 입력되어있습니다.</br>사모채는 채권유형이 특수채일때만 입력가능한 항목입니다.');
        //    		return 1;
        //    	}
    }

    //메시지추가 이자지급주기는 이자계산주기보다 크거나 같아야 합니다.
    let unit = dtsObj.getCellData(1, "intPayUnitMms");
    let calc = dtsObj.getCellData(1, "intPayCalcMms");
    if (unit == '') unit = 0;
    if (calc == '') calc = 0;
    if (parseInt(unit) < parseInt(calc)) {
        if (!await $c.win.confirm('이자지급주기는 이자계산주기보다 크거나 같아야 합니다.</br>그래도 계속하시겠습니까?')) return 1;
    }
    if (dtsObj.getCellData(1, "hbrdbndYn") == '') {
        $c.win.alert("신종자본증권여부를 선택하십시오.");
        return 1;
    } else if (dtsObj.getCellData(1, "hbrdbndYn") == 'Y') {
        if (dtsObj.getCellData(1, "condCapSecuTpCd") != '') {
            $c.win.alert('신종자본증권일 경우 조건부자본증권 유형을 선택하실 수 없습니다.');
            return 1;
        }
        //추가:신종자본증권여부에 "Y"일 때 선/후/중순위에 "4.후후순위"가 아닐 경우, 채무변제 후후순위인지 확인하십시오. 그래도 진행하시겠습니까?
        else if (dtsObj.getCellData(1, "debtRepayRankTpCd") != '4') {
            if (!await $c.win.confirm('채무변제 후후순위인지 확인하십시오.</br>그래도 계속하시겠습니까?')) return 1;
        }
    }

    //추가:4.후후순위인데 신종자본증권여부가 "N"일 경우, 신종자본증권여부를 확인하십시오. 그래도 진행하시겠습니까?  
    if (dtsObj.getCellData(1, "debtRepayRankTpCd") == '4' &&
        dtsObj.getCellData(1, "hbrdbndYn") == 'N') {
        if (!await $c.win.confirm('신종자본증권여부를 확인하십시오.</br>그래도 계속하시겠습니까?')) return 1;
    }

    //주식관련사채 체크 추가
    if (dtsObj.getCellData(1, "nusualBndTpCd") == '2' &&
        dtsObj.getCellData(1, "stkRelCorpbndRghtTpCd") == '') {
        if (!await $c.win.confirm('주식관련탭 권리구분을  선택하셔야 합니다.</br>그래도 계속하시겠습니까?')) return 1;
    }

    //조건부자본증권 추가
    if (dtsObj.getCellData(1, "condCapSecuTpCd") != '') {
        //전환형이면
        if (dtsObj.getCellData(1, "condCapSecuTpCd") == '1') {
            //특이채권유형이 주식관련사채여야 한다.
            if (dtsObj.getCellData(1, "nusualBndTpCd") != '2') {
                $c.win.alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.</br>특이채권유형을 확인바랍니다.');
                return 1;
            }
            // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.

            //주식관련사채이면 '11 조건부자본증권 전환형'이여야 한다.

            //else if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") != '11') {

            //	$c.win.alert('주식관련탭 권리구분을 조건부자본증권 전환형으로 선택하셔야 합니다.'); 

            //	return 1;

            //}

        }
        //상각형이면 특이채권유형이 일반사채이여야 한다.
        else if (dtsObj.getCellData(1, "condCapSecuTpCd") == '2' &&
            dtsObj.getCellData(1, "nusualBndTpCd") != '1') {
            $c.win.alert('특이채권유형을 일반사채로 선택하셔야 합니다.</br>특이채권유형을 확인바랍니다.');
            return 1;
        }
    }
    // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.
    //if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") == '11') {
    //	if(dtsObj.NameValue(1, "nusualBndTpCd") != '2') {
    //    	$c.win.alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.</br>특이채권유형을 확인바랍니다.'); 
    //		return 1;    		
    //	}else if(dtsObj.NameValue(1, "COND_CAP_SECU_TP_CD") != '1') {
    //    	$c.win.alert('조건부자본증권유형을 전환형으로 선택하셔야 합니다.</br>조건부자본증권유형을 확인바랍니다.'); 
    //		return 1;    		    		
    //	}
    //}

    //낙찰금리 필터링 추가 ,GB035(국고채권), 한국은행(AB101), 예금보험공사(AB526)
    //if(dtsObj.NameValue(1, "BND_MKTACT_TP_CD") != '316') {
    //    let isurcd = dtsObj.NameValue(1, "ISUR_CD");
    //    if(dtsObj.NameValue(1, "scbdInt") == ''
    //    	&& (isurcd == 'GB035' || isurcd == 'AB101' || isurcd == 'AB526')) {
    //    	if(! await $c.win.confirm('낙찰금리란에 값이  없습니다.</br>그래도 계속하시겠습니까?')) return 1; 
    //    }    	
    //}

    if (dtsObj.getCellData(1, "redmptMethdTpCd") != '2' &&
        dtsObj.getCellData(1, "splitRedmptTpCd") != '') {
        $c.win.alert("분할상환탭은 분할상환시에만 입력합니다. 상환방법을 확인바랍니다.");
        return 1;
    }
    if ($p.getComponentById("edt_GrtYd") != '') {
        if ($p.getComponentById("edt_GrtYd") >= 20) {
            msg = "" + "보장수익률이 20%이상입니다. " + "</br>계속 진행하시겠습니까?";
            if (!await $c.win.confirm(msg)) return 1;
        }
        if ($p.getComponentById("edt_ExpRedmptRto") == '100') {
            msg = "" + "보장수익률이 존재하고, 만기상환율이 100%입니다. " + "</br>계속 진행하시겠습니까?";
            if (!await $c.win.confirm(msg)) return 1;
        }
    }
    if ($p.getComponentById("cmb_AsstSecutizTpCd") != '' &&
        ($p.getComponentById("cmb_CreditValuInstCd1") == '' || $p.getComponentById("cmb_SfValuYn1") != 'Y') &&
        ($p.getComponentById("cmb_CreditValuInstCd2") == '' || $p.getComponentById("cmb_SfValuYn2") != 'Y') &&
        ($p.getComponentById("cmb_CreditValuInstCd3") == '' || $p.getComponentById("cmb_SfValuYn3") != 'Y') &&
        ($p.getComponentById("cmb_CreditValuInstCd4") == '' || $p.getComponentById("cmb_SfValuYn4") != 'Y')) {
        msg = "" + "유동화채권임에도 SF를 선택하지 않았습니다. " + "</br>계속 진행하시겠습니까?";
        if (!await $c.win.confirm(msg)) return 1;
    }
    return 0;
};

/**
 * @method
 * @name getMsgChkBndClssAndIsur
 * @description chkBndClssAndIsur 체크 결과 메시지를 리턴한다.
 * @param {string} result desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getMsgChkBndClssAndIsur = function (result) {
    let msg = "";
    if (result[0] == 1) {
        msg = "채권분류코드가 발행기관코드와 일치하지 않습니다.</br>";
        //msg += "채권분류코드 등을 다시 확인해 주시기 바랍니다.";
        msg += "발행기관 채권분류 관리를 참고하여 확인하시기 바랍니다.";
    } else if (result[0] == 2) {
        msg = "채권분류코드가 채권유형과 일치하지 않습니다.</br>";
        msg += "채권분류코드 등을 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 3) {
        //msg = "채권분류코드가 채권유형 </br>또는 주식관련구분 등과 일치하지 않습니다.</br>";
        msg = "채권분류코드가 채권유형과 일치하지 않습니다.</br>";
        msg += "발행기관 채권분류 관리를 참고하여 확인하시기 바랍니다.";
    } else if (result[0] == 4) {
        msg = "채권분류코드가 주식관련 </br>또는 권리구분 등과 일치하지 않습니다.</br>";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 5) {
        msg = "채권분류코드가 통화표시와 일치하지 않습니다.</br>";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 7) {
        msg = "채권분류코드가 지방채구분 </br>또는 발행기관코드와 일치하지 않습니다.</br>";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 8) {
        msg = "채권분류코드가 지방채구분과 일치하지 않습니다.</br>";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 9) {
        msg = "채권분류코드가 국내채여부(FO 외국채권)와 일치하지 않습니다.</br>";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 11) {
        msg = "주식관련권리구분이 분리형인 경우 </br>주식관련사채가 아닙니다.</br>";
        msg += "관련항목을 확인해주시기 바랍니다.";
    }
    if (result[1] == 6) {
        if (result[0] == 0) {
            msg = "유동화구분이 발행기관과 일치하지 않습니다.";
        } else {
            msg = "</br>--------------------------------------------------------------</br>";
            msg += "유동화구분이 발행기관과 일치하지 않습니다.";
        }
        msg += "</br>유동화구분 등을 다시 확인해 주시기 바랍니다.";
    }
    msg += "</br></br> 처리하시겠습니까?";
    return msg;
};

/**
 * @method
 * @name chkBndClssAndIsur
 * @description 채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} BND_MKTACT_TP_CD desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkBndClssAndIsur = async function (vScrenID, dtsObj, BND_MKTACT_TP_CD) {
    let rgtCd = dtsObj.get("stkRelCorpbndRghtTpCd"); //권리구분
    let liqCd = dtsObj.get("asstSecutizTpCd"); //유동화구분
    let isurCd = dtsObj.get("isurCd"); //발행기관코드
    let isurNm = $p.getComponentById("txb_IsurNm").getValue(); //발행기관명
    let localCd = dtsObj.get("munibndTpCd"); //지방채구분
    let bndTpCd = dtsObj.get("bndTpCd"); //채권유형
    let mktRsnCd = BND_MKTACT_TP_CD; //시장조치
    let currTpCd = dtsObj.get("currTpCd"); //통화구분
    let bndClssCd = dtsObj.get("bndClssCd"); //채권분류코드
    let nusualBndTpCd = dtsObj.get("nusualBndTpCd"); //주식관련
    let ischeck = true;
    if (BND_MKTACT_TP_CD == "203") {
        bndTpCd = dtsObj.get("AFCHG_BND_TP_CD"); //채권유형
        bndClssCd = dtsObj.get("AFCHG_BND_CLASS_CD"); //채권분류코드
        ischeck = false;
    }
    ///////////////////////////////////////////////////////////////////////
    // 1. 통화표시체크
    // 2달러 : 채권분류코드(310000), 3엔화 : 채권분류코드(320000)
    // 그 이외의 통화표시선택하면 주식관련/권리구분 체크로 넘어감.
    // 2. 국내채여부체크
    // 외국채권(FO) : 외국채권(130000)
    // 3. 주식관련/권리구분
    // 주식관련이 주식관련채권(2)를 선택한 경우에만 체크함.
    // 주식관련채권+전환권 : 채권분류코드(116510), 주식관련채권+신주인수권비분리형 : 116520, 주식관련채권+교환권비분리형 : 116530, 주식관련채권+이익참가권 : 116540
    // 주식관련이 주식관련채권 이외의 경우에는 발행기관과 채권유형 체크로 넘어감.
    //////////////////////////////////////////////////////////////////////

    let result = new Array();
    result[0] = 0;
    result[1] = 0;

    /**
     * 외화표시채권 310000, 320000, 330000 삭제됨
     * 스트립채권 411000 삭제됨
     */
    //USD
    if (currTpCd == '2') {
        //달러표시채권
        /**
        if(bndClssCd == "310000")	result[0] = 0;
        else						result[0] = 5;
        result[1] = isLiqCheck(isurCd, isurNm, liqCd);
         */
        result[0] = 0;
        result[1] = await scwin.isLiqCheck(isurCd, isurNm, liqCd);
    }
    //JPY
    else if (currTpCd == '3') {
        /**
        if(bndClssCd == "320000")	result[0] = 0;
        else						result[0] = 5;
        result[1] = isLiqCheck(isurCd, isurNm, liqCd);
         */
        //엔화표시채권
        result[0] = 0;
        result[1] = await scwin.isLiqCheck(isurCd, isurNm, liqCd);
    }
    //EUR
    else if (currTpCd == '4') {
        /**
        if(bndClssCd == "330000")	result[0] = 0;
        else						result[0] = 5;
        result[1] = isLiqCheck(isurCd, isurNm, liqCd);
         */
        //유로화표시채권
        result[0] = 0;
        result[1] = await scwin.isLiqCheck(isurCd, isurNm, liqCd);
    } else {
        //외국채
        if (bndTpCd == "FO") {
            //외국채권
            if (bndClssCd == "130000") result[0] = 0;

            else result[0] = 9;
            result[1] = await scwin.isLiqCheck(isurCd, isurNm, liqCd);
        } else {
            /**
             * 무조건 발행기관별 채권분류 체크하기
             */
            result = await scwin.isIssinstcd(vScrenID, mktRsnCd, bndTpCd, nusualBndTpCd, localCd, bndClssCd, isurCd, isurNm, liqCd, ischeck);
            if (await scwin.checkRgtcd(nusualBndTpCd, rgtCd, mktRsnCd)) {
                result[0] = 10;
                result[1] = 10;
                $c.win.alert("주식관련여부가 주식관련채권(2)인 </br>경우에는 권리구분을 선택하십시오.");
                return result;
            }
            if (nusualBndTpCd == '2' && rgtCd != '') {
                result = await scwin.isRgtcd(rgtCd, bndClssCd, isurCd, isurNm, liqCd);
            } else {
                /**
                 * 상단으로 이동
                result = isIssinstcd(vScrenID, mktRsnCd, bndTpCd, nusualBndTpCd, localCd, bndClssCd, isurCd, isurNm, liqCd, true);
                 */
            }
        }
    }
    if (result[0] == 10 && result[1] == 10) {
        return 1;
    } else if (result[0] == 0 && result[1] == 0) {
        //skip

    } else {
        if (!await $c.win.confirm(await scwin.getMsgChkBndClssAndIsur(result))) return 1;
    }
    return 0;
};

