/**
 * @method
 * @name checkFee
 * @description 신규,변경상장 수수료를 체크한다.
 * @param {string} screnId desc
 * @param {string} eachGp desc
 * @param {string} dtsObj desc
 * @param {string} bndApplId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkFee = async function (eachGp, bndApplId) {

    let res = await scwin.getCheckUrl('', bndApplId, 'N');
    if(res.responseJSON.success){
        console.log("checkFee done :" + res.responseJSON.body.VALID_FEE_NEW);

        if (eachGp == "1") {
            if (res.responseJSON.body.VALID_FEE_NEW == "Y") {
                await $c.win.alert("수수료그룹지정이 안된종목입니다. 수수료그룹지정을 하십시오!"); return 5;
            }
        } else if (eachGp == "2") {
            if (res.responseJSON.body.VALID_FEE_CHG == "Y") {
                await $c.win.alert("수수료그룹지정이 안된종목입니다. 수수료그룹지정을 하십시오!"); return 5;
            }
        }
    }

    return 0;
}

