/**
 * @method
 * @name hasAttachDoc
 * @description 첨부문서 및 팩스문서를 체크한다.
 * @param {string} vScrenID desc
 * @param {string} dtsObj dataset
 * @param {string} vBndApplId 채권신청번호
 * @param {string} vBndListProcsTpCd 처리구분코드
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.hasAttachDoc = async function (vScrenID, dtsObj, vBndApplId, vBndListProcsTpCd) {
    const reqMap = {
        vBndApplId : vBndApplId,
        vBndListProcsTpCd : vBndListProcsTpCd
    }

    const sbmOptions = {
        id: "sbm_bndattachDocYn",
        action: "/api/bonds/bndNew/attachDocYn-select",
        method: "get",
        target: "dma_bndattachDocYnEnd=body",
        // gridview: "grd_List1,grd_List2",
        submitDoneHandler: scwin.sbm_bndattachDocYn_submitdone, isProcessMsg: false
    };

    await $c.sbm.executeDynamic(sbmOptions , reqMap);

    if ("N" == dtsObj.get("HAS_ATTACH_DOC")) {
        await $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
        return 1;
    }
    return 0;
};

