/**
 * @method
 * @name checkAcptProcStrtDd
 * @description 접수처리/처리완료시 해당종목이 이미 조치일이 같은일자로 시장조치 대기중인지 체크
 *              => 320(일별금액조정), 201(상호변경), 일괄상장 연간등록 해당없음
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} strtDd desc
 * @param {string} bndApplId desc
 * @param {string} isuCd desc
 * @param {string} processGp desc
 * @param {string} mktactTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkAcptProcStrtDd = function (vScrenID, dtsObj, strtDd, bndApplId, isuCd, processGp, mktactTpCd) {
    let param = '';
    param += "&{P}V_BND_APPL_ID=" + bndApplId;
    param += "&{P}V_STRT_DD=" + strtDd;
    param += "&{P}V_ISU_CD=" + isuCd;
    param += "&{P}V_MKTACT_TP_CD=" + mktactTpCd;
    let qryId = '';
    let dsNm = 'BNS_ACPT_STRT_DD_CHECK';
    if (processGp == "1") {
        //접수
        qryId = "lds.stf.bnscommon.select.acptStrtDdCheck";
    } else if (processGp == "3") {
        //처리완료
        qryId = "lds.stf.bnscommon.select.procStrtDdCheck";
    }
    dtsObj.SyncLoad = "true";
    scwin.searchBns(vScrenID, dtsObj, dsNm, qryId, param);
    return 0;
};

