/**
 * @method
 * @name rowPos
 * @description DataSet Reset시 해당 ROW로 이동
 *              예) - [변수 초기화] let vRowPos = 0;
 *                  - [버튼 OnClick] vRowPos = dts_List.RowPosition;
 *                  - [접수내역 OnLoadCompleted 시] 수정,처리완료,팀장확인 시 해당 ROW로 이동 → rowPos(dts_List, vRowPos);
 * @param {string} dtsObj desc
 * @param {string} vRowPos desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.rowPos = function (dtsObj, vRowPos) {
    if (vRowPos.length != 12 && vRowPos > -1) {
        dtsObj.setRowPosition(vRowPos);
        console.log("vRow : " + dtsObj.getRowPosition());
    }
};

/**
 * @method
 * @name checkMultActImpsblRule
 * @description 해당종목의 복수조치 건이 접수되어 있는지 체크
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} vIsuCd desc
 * @param {string} vMktactCd desc
 * @param {string} vStrtDd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkMultActImpsblRule = function (vScrenID, dtsObj, vIsuCd, vMktactCd, vStrtDd) {
    let dsNm = 'BNS_MULTACT_IMPSBLE_RULE';
    let qryId = 'lds.stf.bnscommon.select.readMultActImpsblRule';
    let param = '';
    param += '&{P}V_STD_CD=' + vIsuCd;
    param += '&{P}V_BND_MKTACT_TP_CD=' + vMktactCd;
    param += '&{P}V_STRT_DD=' + vStrtDd;
    dtsObj.SyncLoad = "true";
    scwin.searchBns(vScrenID, dtsObj, dsNm, qryId, param);
    let output = '복수조치가 불가능한 시장조치입니다.';
    output += '</br>' + '해당종목에 대하여 적용일이 동일한 신청내역을 검토하여 주십시오.';
    if (dtsObj.getCellData(1, 'MULTACT_IMPSBL_CNT') > 0) {
        $c.win.alert(output);
        return 1;
    }
    return 0;
};

