/**
 * @method
 * @name checkGridMaxLength
 * @description 그리드 입력 시, maxLength 체크
 * @param {string} dtsObj desc
 * @param {string} ColID desc
 * @param {string} size desc
 * @param {string} lbl desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkGridMaxLength = function (dtsObj, ColID, size, lbl) {
    for (let i = 1; i <= dtsObj.getTotalRow(); i++) {
        let value = dtsObj.getCellData(i, ColID);
        let overLen = eval($c.stf.getStringSize(value) - size);
        let checkRow = dtsObj.NameValueRow(ColID, value);
        if (overLen > 0) {
            $c.win.alert(checkRow + "행의 " + "[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    </br></br>[ " + overLen + " ] byte 를 초과하였습니다.</br></br>확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
            dtsObj.setFocusedCell(checkRow, 0);
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name replaceSpecialChar
 * @description ASCⅡ로 등록된 특수문자 되돌리기(일반 컴포넌트)
 *              DataSet OnLoadCompleted 시점에서 적용 (14.01.xx 현재는 미사용 중)
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.replaceSpecialChar = function (str) {
    if (str == null) return "";
    str = str.replace(/&lt;/gi, '<');
    str = str.replace(/&gt;/gi, '>');
    str = str.replace(/&amp;/gi, '&');
    str = str.replace(/&quot;/gi, '"');
    str = str.replace(/&apos;/gi, "'");
    str = str.replace(/&#37;/gi, '%');
    str = str.replace(/&#59;/gi, '?');
    str = str.replace(/&#61;/gi, '=');
    str = str.replace(/&#46;/gi, '.');
    str = str.replace(/&#47;/gi, '/');
    return str;
};

