/**
 * @method
 * @name addCheck
 * @description 고객 요청에의한 체크 추가 2024-06-05 by 김효준
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addCheck = async function (dtsObj) {
    // 회사채 & 보증/담보 in (무보증,정부보증,부분보증) & (발행금액 or 상장금액 < 3억)
    if (dtsObj.get("bndTpCd") == "CO" &&
        (dtsObj.get("bndGuarTpCd") == "2" || dtsObj.get("bndGuarTpCd") == "4" || dtsObj.get("bndGuarTpCd") == "5") &&
        (dtsObj.get("isuAmt") < 300000000 || dtsObj.get("listAmt") < 300000000)) {
        let msg = "무보증/정부보증/부분보증 회사채의 발행/상장금액이 3억원 미만으로 입력되었습니다.</br></br>계속 진행하시겠습니까?";
        if (! await $c.win.confirm(msg)) return 1;
    }

    // 회사채 & 보증/담보 in (보증,담보부,커버드본드) & (발행금액 or 상장금액 < 5천만)
    if (dtsObj.get("bndTpCd") == "CO" &&
        (dtsObj.get("bndGuarTpCd") == "1" || dtsObj.get("bndGuarTpCd") == "3" || dtsObj.get("bndGuarTpCd") == "6") &&
        (dtsObj.get("isuAmt") < 50000000 || dtsObj.get("listAmt") < 50000000)) {
        let msg = "보증/담보부/커버드본드 회사채의 발행/상장금액이 5천만원 미만으로 입력되었습니다.</br></br>계속 진행하시겠습니까?";
        if (! await $c.win.confirm(msg)) return 1;
    }

    // 과세여부 비과세인경우.(대부분 과세)
    if (dtsObj.get("taxYn") == "N") {
        if (! await $c.win.confirm("과세여부가 \"비과세\"로 설정되어 있습니다.</br></br>계속 진행하시겠습니까?")) return 1;
    }

    // 기명구분이 기명인경우.(대부분 무기명)
    if (dtsObj.get("SIGN_YN") == "Y") {
        if (! await $c.win.confirm("기명구분이 \"기명\"으로 설정되어 있습니다.</br></br>계속 진행하시겠습니까?")) return 1;
    }
    // let tmp = document.getElementById("cmb_DebtRepayRankTpCd").getText();
    // // 선/후/중순위가 선순위가 아닌경우.(대부분 선순위)
    // if (dtsObj.get("debtRepayRankTpCd") != "1") {
    //     if (!$c.win.confirm("선/후/중순위가 \"" + tmp + "\"으로 설정되어 있습니다.</br></br>계속 진행하시겠습니까?")) return 1;
    // }
    return 0;
};

/**
 * @method
 * @name getBusinessDay
 * @description 기준일로부터 영업일 기준으로 T-offPrev ~ T+offNext
 *              offPrev : 기준일로부터 offPrev 영업일 전. 항상 양수로 입력..
 *              offNext : 기준일로부터 offNext 영업일 후. 항상 양수로 입력..
 * @param {string} vScrenID desc
 * @param {string} vDataSet desc
 * @param {string} base_dt desc
 * @param {string} offPrev desc
 * @param {string} offNext desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getBusinessDay = function (vScrenID, vDataSet, base_dt, offPrev, offNext) {
    let param = '';
    param += "&{P}v_baseDt=" + base_dt;
    param += "&{P}v_offPrev=" + offPrev;
    param += "&{P}v_offNext=" + offNext;
    vDataSet.syncload = "true";
    let dsId = "BNS_BUSINESS_DAY_INFO";
    let qryId = "lds.stf.bnscommon.select.getBusinessDay";
    scwin.searchBns(vScrenID, vDataSet, dsId, qryId, param);
};
